import React, { useEffect, useState } from "react";

function App() {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const evtSource = new EventSource("http://127.0.0.1:8000/api/question1");

    evtSource.onmessage = (e) => {
      try {
        const data = JSON.parse(e.data);
        setEvents((prev) => [...prev, data]);
      } catch (err) {
        console.error("Bad event:", e.data);
      }
    };

    evtSource.onerror = (err) => {
      console.error("EventSource failed:", err);
      evtSource.close();
    };

    return () => {
      evtSource.close();
    };
  }, []);

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4">Prime Search Progress</h1>
      <div className="space-y-2 max-h-[70vh] overflow-y-auto border rounded p-4 bg-gray-900 text-green-300 font-mono">
        {events.map((ev, idx) => (
          <div key={idx}>
            {ev.i && ev.checking && (
              <div>🔍 Checking i = {ev.i}</div>
            )}
            {ev.base && (
              <div>
                Round {ev.round}, base = {ev.base}, x = {ev.x}
              </div>
            )}
            {ev.square_step && (
              <div>
                &nbsp;&nbsp;Square step {ev.square_step}, x = {ev.x}
              </div>
            )}
            {ev.result === "composite" && (
              <div className="text-red-400">❌ Composite</div>
            )}
            {ev.result === "probably_prime" && (
              <div className="text-green-400">✅ Probably Prime</div>
            )}
            {ev.prime && (
              <div className="text-green-500 font-bold">
                🎉 Found Prime at i = {ev.i} (method: {ev.method})
              </div>
            )}
            {ev.done && (
              <div className="text-yellow-400 font-bold">⚠️ Done (no prime found)</div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
